package com.inventra.backend.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDateTime;
@Document(collection="returns") public class ReturnRecord { @Id private String id; private String orderId; private String warehouseId; private String productId; private int quantity; private String reason; private ReturnStatus status=ReturnStatus.REQUESTED; private LocalDateTime createdAt=LocalDateTime.now(); private LocalDateTime completedAt; public ReturnRecord(){} public String getId(){return id;} public void setId(String v){id=v;} public String getOrderId(){return orderId;} public void setOrderId(String v){orderId=v;} public String getWarehouseId(){return warehouseId;} public void setWarehouseId(String v){warehouseId=v;} public String getProductId(){return productId;} public void setProductId(String v){productId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public ReturnStatus getStatus(){return status;} public void setStatus(ReturnStatus v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getCompletedAt(){return completedAt;} public void setCompletedAt(LocalDateTime v){completedAt=v;} }
